class SendMessageDialogController{constructor($mdDialog,DispatchData,toastrService,selectedCourierId,contactId,dispatcherName){this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this._selectedCourierId=selectedCourierId;this._contactId=contactId;this._dispatcherName=dispatcherName;this.isLoading=false;this.message=""}async submit(message){try{this.isLoading=true;await this.DispatchData.sendSMS(this._selectedCourierId,this._contactId,this._dispatcherName,message);this.toastrService.showSuccessToast("Message sent!")}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.isLoading=false;this.$mdDialog.hide()}}cancel(){this.$mdDialog.cancel()}}